local cachedResult = nil
local baseAddresses = {TRAIN = nil, HELICOPTER = nil, PLANE = nil, TRAIN_STATION = nil, HELICOPTER_PAD = nil, AIRPORT = nil, SHIP = nil, PORT = nil, COW = nil, CHICKEN = nil, SHEEP = nil, PIG = nil, ISLAND = nil}
local tableA = nil
local basePointer = nil
local unique_cachedGiftResults = nil
local unique_tableA = nil
local unique_cachedPointerResults = nil
local cachedTrainResults = nil
local cachedLandResults = nil
local cachedAddFriendResults = nil
local cachedFlipTilesResults = nil
local cardsEnabled = false
local cardsCached = false
