    freezeItems = {},
    values1 = {},
    values2 = {}
}
local cloverEnabled = false
clanAchievementsCached = false
clanAchievementsResults = nil
local cloverFreezeItems = {}
local stateFile = gg.EXT_CACHE_DIR .. "/pointer_results.txt"
os.remove(stateFile)


function savePointerResults(results)
    local f = io.open(stateFile, "w")
    if f then
        for _, r in ipairs(results) do
            f:write(tostring(r.address) .. "\n")
        end
        f:close()
    end
end

-- دالة تحميل النتائج
function loadPointerResults()
    local results = {}
    local f = io.open(stateFile, "r")
    if f then
        for line in f:lines() do
            table.insert(results, {address = tonumber(line), flags = 4})
        end
        f:close()
        return #results > 0 and results or nil
    end
    return nil
end

function selectAll()

    local menu = {}

    for i, v in ipairs(resources) do
        table.insert(menu, v.section)
    end

    table.insert(menu, "⬅️ رجوع")

    local choice = gg.choice(menu, nil, "📦 اختر القسم الذي تريد تطبيق جميع عناصره")

    if not choice or choice == #menu then
        return
    end

    local sectionData = resources[choice]

    if not sectionData or not sectionData.items or #sectionData.items == 0 then
        gg.alert("لا توجد عناصر في هذا القسم ❌")
        return
    end

    -- رسالة موحدة لإدخال القيمة لجميع عناصر القسم
    local promptMsg = "اكتب الرقم الذي تريد تطبيقه على جميع عناصر قسم (" .. sectionData.section .. ") :"
    local userInput = gg.prompt({promptMsg}, nil, {"number"})
    if not userInput then
        return
    end

    local countVal = tonumber(userInput[1])
    if userInput[1] == "" or countVal == nil then
        gg.alert("لم يتم إدخال عدد صحيح .. حاول مجدداً 😁")
        return
    end

    -- تهيئة نتائج الهدية الأساسية إن لم تكن موجودة
    if unique_cachedGiftResults == nil then
        gg.toast("🇦 🇭 🇲 🇪 🇩")
        gg.clearResults()
        gg.searchNumber("65538;1;1;12546::113", 4)
        gg.refineNumber("65538", 4)
        unique_cachedGiftResults = gg.getResults(gg.getResultCount())
        
        if #unique_cachedGiftResults == 0 then 
            gg.alert("لم يتم العثور على الهدية 29!") 
            gg.setVisible(true)
            return 
        end
    end

    -- تجهيز المؤشرات إن وجدت (مرة واحدة لتوفير الوقت)
    local hasPointer = false
    for _, item in ipairs(sectionData.items) do
        if item.isPointer then hasPointer = true break end
    end

    if hasPointer then
        if unique_tableA == nil then
            gg.clearResults()
            gg.searchNumber("1768641320;1918132078;1601071457;1768058738;33;27::57", 4)
            gg.refineNumber("33", 4)
            local res = gg.getResults(1)
            if #res == 0 then 
                gg.alert("لم يتم العثور ع كود استبدال المؤشر") 
                gg.setVisible(true) 
                return 
            end
            unique_tableA = {}
            for i = 0, 5 do table.insert(unique_tableA, gg.getValues({{address = res[1].address + (i * 4), flags = 4}})[1].value) end
        end

        if unique_cachedPointerResults == nil then
            unique_cachedPointerResults = loadPointerResults()
        end
        
        if unique_cachedPointerResults == nil then         
            gg.clearResults()
            gg.searchNumber("1852402515;1634882655;1951624809;1869182049;1869766510;1215195490;6582127::25", 4)
            gg.refineNumber("1852402515", 4)
            local count = gg.getResultCount()
            if count == 0 then 
                gg.alert("لم يتم العثور ع المؤشر الاساسي") 
                gg.setVisible(true) 
                return 
            end
            unique_cachedPointerResults = gg.getResults(count)
            savePointerResults(unique_cachedPointerResults)
        end
    end

    -- إخفاء القائمة لتسهيل الضغط على الهدية
    gg.setVisible(false)
    gg.toast("⏳ جاهز.. اضغط على الهدية 29 لتطبيق العناصر تباعاً")

    -- التكرار التتابعي المعتمد على تفاعل المستخدم مع اللعبة
    for index, item in ipairs(sectionData.items) do
        
        -- 1. تطبيق العنصر الحالي وجعل القيمة 2
        if item.isPointer then
            local unique_editList = {}
            for _, r in ipairs(unique_cachedGiftResults) do
                table.insert(unique_editList, {address = r.address + 100, value = 2, flags = 4})                
                table.insert(unique_freezeList, {address = r.address + 84, value = 0, flags = 4, freeze = true})
                table.insert(unique_freezeList, {address = r.address + 88, value = 0, flags = 4, freeze = true})
                for i = 0, 5 do table.insert(unique_editList, {address = r.address + 40 + (i * 4), value = unique_tableA[i+1], flags = 4}) end
                table.insert(unique_editList, {address = r.address + 48, value = item.Level, flags = 4})
                table.insert(unique_editList, {address = r.address + 76, value = 0, flags = 4})
                table.insert(unique_editList, {address = r.address + 80, value = countVal, flags = 4})
            end

            local codeCount = #item.Code
            for _, ptr in ipairs(unique_cachedPointerResults) do
                for i = 0, codeCount - 1 do
                    table.insert(unique_editList, {
                        address = ptr.address + (i * 4), 
                        value = item.Code[i+1], 
                        flags = 4
                    })
                end
            end
            gg.setValues(unique_editList)

        else
            local unique_editList = {}
            for _, r in ipairs(unique_cachedGiftResults) do
                    table.insert(unique_editList, {address = r.address + 100, value = 0, flags = 4})
                    for j, h in ipairs(item.Code) do table.insert(unique_editList, {address = r.address + 40 + (j * 4), value = h, flags = 4}) end
                    table.insert(unique_editList, {address = r.address + 76, value = 0, flags = 4})
                    table.insert(unique_editList, {address = r.address + 80, value = countVal, flags = 4})
                
            end
            gg.setValues(unique_editList)
        end

        -- إعلام المستخدم بالعنصر الحالي الذي ينتظر الاستلام
        gg.toast("📦 في انتظار استلام: " .. item.name)

        -- 2. حلقة انتظار ذكية: تراقب القيمة في الذاكرة حتى يتحول الحماس إلى 1 (دليل ضغط المستخدم على الهدية)
        local waitingForClaim = true
        while waitingForClaim do
            gg.sleep(300) -- فحص كل 300 جزء من الثانية لعدم الضغط على المعالج
            
            if unique_cachedGiftResults and #unique_cachedGiftResults > 0 then
                local currentValObj = gg.getValues({{address = unique_cachedGiftResults[1].address + 12, flags = 4}})
                if currentValObj and currentValObj[1] then
                    -- إذا تحولت القيمة إلى 1، فهذا يعني أن المستخدم أخذ الهدية
                    if currentValObj[1].value == 1 then
                        waitingForClaim = false
                    end
                end
            end
        end

        -- إشعار سريع بأن العنصر تم استلامه بنجاح
        gg.toast("✅ تم استلام: " .. item.name)
        gg.sleep(500) -- مهلة قصيرة جداً قبل الانتقال للعنصر التالي
    end

    gg.alert("🎉 تم الانتهاء من تطبيق واستلام جميع عناصر قسم (" .. sectionData.section .. ") بنجاح!")
end



local cachedGiftResults = nil
function applyUnified(item)
    if cachedGiftResults == nil then
        gg.toast("​🇦 🇭 🇲 🇪 🇩")
        gg.clearResults()
        gg.searchNumber("65538;1;1;12546::113", 4)
        gg.refineNumber("65538", 4)
        cachedGiftResults = gg.getResults(gg.getResultCount())
        
        if #cachedGiftResults == 0 then 
            gg.alert("لم يتم العثور على الهدية 29!") 
            return 
        end
    end

    if item.isPointer then
        if tableA == nil then
            gg.clearResults()
            gg.searchNumber("1768641320;1769105507;1634563187;1634882584;33;27::57", 4)
            gg.refineNumber("33", 4)
            local res = gg.getResults(1)
            if #res == 0 then gg.alert("لم يتم العثور ع كود استبدال المؤشر") return end
            tableA = {}
            for i = 0, 5 do table.insert(tableA, gg.getValues({{address = res[1].address + (i * 4), flags = 4}})[1].value) end
        end

        if cachedPointerResults == nil then
            cachedPointerResults = loadPointerResults()
        end
        
        if cachedPointerResults == nil then         
            gg.clearResults()
            gg.searchNumber("1852402515;1634882655;1951624809;1869182049;1751342958;1953720690;7561581::25", 4)
            gg.refineNumber("1852402515", 4)
            local count = gg.getResultCount()
            if count == 0 then gg.alert("لم يتم العثور ع المؤشر الاساسي") return end
            cachedPointerResults = gg.getResults(count)
            savePointerResults(cachedPointerResults)
        end

        local editList, freezeList = {}, {}
        for _, r in ipairs(cachedGiftResults) do
            table.insert(freezeList, {address = r.address + 100, value = 0, flags = 4, freeze = true})
            table.insert(freezeList, {address = r.address + 84, value = 0, flags = 4, freeze = true})
            table.insert(freezeList, {address = r.address + 88, value = 0, flags = 4, freeze = true})
            for i = 0, 5 do table.insert(editList, {address = r.address + 40 + (i * 4), value = tableA[i+1], flags = 4}) end
            table.insert(editList, {address = r.address +48, value = item.Level, flags = 4})
        end

        local codeCount = #item.Code
        for _, ptr in ipairs(cachedPointerResults) do
            for i = 0, codeCount - 1 do
                table.insert(editList, {
                    address = ptr.address + (i * 4), 
                    value = item.Code[i+1], 
                    flags = 4
                })
            end
        end
        
        gg.setValues(editList)
        gg.addListItems(freezeList)
        gg.alert("تم الاستبدال بنجاح ✅️\n\nاذهب واضغط ع الهدية 29 🎁")

    else
      local editList, freezeList = {}, {}
        for _, r in ipairs(cachedGiftResults) do
                table.insert(freezeList, {address = r.address + 100, value = 0, flags = 4, freeze = true})
                table.insert(freezeList, {address = r.address + 84, value = 0, flags = 4, freeze = true})
                table.insert(freezeList, {address = r.address + 88, value = 0, flags = 4, freeze = true})
                for j, h in ipairs(item.Code) do table.insert(editList, {address = r.address + 36 + (j * 4), value = h, flags = 4}) end
                table.insert(editList, {address = r.address + 76, value = 0, flags = 4})
                table.insert(editList, {address = r.address + 80, value = 1, flags = 4})
          
        end
        gg.setValues(editList)
        gg.addListItems(freezeList)
        gg.alert("تم الاستبدال بنجاح ✅️\n\nاذهب واضغط ع الهدية 29 🎁")
    end
    gg.setVisible(false)
end


function applySkins(skinData, typeKey)
    if cachedGiftResults == nil then
        gg.toast("❤️ صلي على النبي ❤️")
        gg.clearResults()
        gg.searchNumber("65538;1;1;12546::113", 4)
        gg.refineNumber("65538", 4)
        local count = gg.getResultCount()
        if count == 0 then gg.alert("لم يتم العثور على الهدية 29!") return end
        cachedGiftResults = gg.getResults(count)
    end
    if baseAddresses[typeKey] == nil then
        gg.clearResults()
        local search = skin_searches[typeKey]
        gg.searchNumber(search.code, 4)
        gg.refineNumber(search.refine, 4)
        local results = gg.getResults(1)
        if #results == 0 then gg.alert("لم يتم العثور على " .. typeKey) return end
        baseAddresses[typeKey] = results[1].address
    end
    local currentBase = baseAddresses[typeKey] + skinData.offset
    local values = gg.getValues({{address = currentBase, flags = 4}, {address = currentBase+4, flags = 4}, {address = currentBase+8, flags = 4}, {address = currentBase+12, flags = 4}, {address = currentBase+16, flags = 4}, {address = currentBase+20, flags = 4}})
    local editList, freezeList = {}, {}
    for _, r in ipairs(cachedGiftResults) do
        table.insert(freezeList, {address = r.address + 100, value = 0, flags = 4, freeze = true})
        table.insert(freezeList, {address = r.address + 84, value = 0, flags = 4, freeze = true})
        table.insert(freezeList, {address = r.address + 88, value = 0, flags = 4, freeze = true})
        for j = 0, 5 do table.insert(editList, {address = r.address + 40 + (j * 4), value = values[j+1].value, flags = 4}) end
    end
    gg.setValues(editList)
    gg.addListItems(freezeList)
    gg.toast("تم حقن " .. skinData.name .. " بنجاح ✅")
    gg.alert("تم الاستبدال بنجاح ✅️\n\nاذهب واضغط ع الهدية 29 🎁")
end

function applyTicket()
    gg.setVisible(false) 
    gg.toast("🇦 🇭 🇲 🇪 🇩")   
    gg.clearResults() 
    gg.searchNumber("1634038552;1937011470;700~10000::121", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    gg.refineNumber("700~10000", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    
    local results = gg.getResults(100) 
    local count = #results
    
    if count == 0 then
        gg.alert("لم يتم العثور على نتائج!")
        return
    end

    local modifications = {}
    for i = 1, count do
        local baseAddress = results[i].address
        table.insert(modifications, {address = baseAddress + 0xD0, value = 0, flags = gg.TYPE_DWORD})
        table.insert(modifications, {address = baseAddress + 0xD0 + 4, value = 700, flags = gg.TYPE_DWORD})
        table.insert(modifications, {address = baseAddress + 0xD0 + 16, value = 1, flags = gg.TYPE_DWORD})
    end
    
    gg.setValues(modifications)
    gg.toast("تم فتح التصريح بنجاح ✅️")
    saveState("TICKET_MENU", "0")
    gg.setVisible(false)
return
end

function getTicketID(input)
    local num = tonumber(input)
    if num then return num end
    for _, v in ipairs(tickets_id) do
        if v.name == input then return v.id end
    end
    return nil
end

function changeTicket(srcInput, destInput)
    local idSrc = getTicketID(srcInput)
    local idDest = getTicketID(destInput)

    if not idSrc or not idDest then
        gg.alert("تأكد من كتابة ارقام التصريح 🫠")
        return
    end
    gg.toast(" ❤️ صلي على النبي ❤️ ")
    gg.clearResults()
    gg.searchNumber("1634038552;1937011470;700~10000::121", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    gg.refineNumber("700~1000", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    
    local results = gg.getResults(100)
    local srcAddress = nil
    local destAddresses = {}

    for _, v in ipairs(results) do
        if v.value == idSrc and srcAddress == nil then srcAddress = v.address end
        if v.value == idDest then table.insert(destAddresses, v.address) end
    end

    if not srcAddress or #destAddresses == 0 then
        gg.alert("ارقام التصريح الذي ادخلتها خاطئة ❌️ ، راجع إرشادات التصريحات 📖")
        return
    end

    local sourceValues = {}
    for i = 0, 255 do
        sourceValues[i + 1] = {address = srcAddress - 0x1E8 + (i * 4), flags = gg.TYPE_DWORD}
    end
    
    local data = gg.getValues(sourceValues)
    
    local allTargetValues = {}
    for _, dAddr in ipairs(destAddresses) do
        for i = 0, 255 do
            table.insert(allTargetValues, {
                address = dAddr - 0x1E8 + (i * 4), 
                flags = gg.TYPE_DWORD, 
                value = data[i + 1].value
            })
        end
    end
    
    gg.setValues(allTargetValues)
    gg.clearResults()
    gg.alert("✅️ تم تبديل التصريح بنجاح!\n\n⚠️ يجب عليك إغلاق اللعبة وإعادة فتحها لمشاهدة التغييرات.")
    saveState("TICKET_MENU", "0")
    gg.setVisible(false)
end


function searchByName(defaultChoice, lastQuery)
    local userInput = lastQuery
    if not userInput then
        local input = gg.prompt({" أدخل اسم الشيء الذي تريده : "}, nil, {"text"})
        if not input or trim(input[1]) == "" then 
            mainMenu() 
            return 
        end
        userInput = trim(input[1]):lower()
    end
    
    local matches = {}
    for _, sect in ipairs(config) do 
        for _, item in ipairs(sect.items) do 
            if trim(item.name):lower():find(userInput) then table.insert(matches, {data = item, type = "U"}) end 
        end 
    end
    for _, item in ipairs(Decors) do
        if trim(item.Name):lower():find(userInput) then table.insert(matches, {data = item, type = "U"}) end
    end
    for k, cat in pairs(skins) do
        for _, item in ipairs(cat) do
            if trim(item.name):lower():find(userInput) then table.insert(matches, {data = {item = item, key = k}, type = "S"}) end
        end
    end
    
    if #matches == 0 then
        gg.alert("لا يوجد شيء بهذا الاسم ❌️")
        mainMenu()
    else
        local names = {"⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة", "🔍 البحث عن شيء آخر"}
        for _, m in ipairs(matches) do
            table.insert(names, m.data.name or m.data.Name or m.data.item.name)
        end
        table.insert(names, "🔍 البحث عن شيء آخر")
        table.insert(names, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")
        
        saveState("SEARCH_MENU", userInput .. "|" .. tostring(defaultChoice or 1))
        
        local choice = gg.choice(names, tonumber(defaultChoice) or 3, "نتائج البحث التي تحتوي على: " .. userInput)

        
        if choice == nil then 
            gg.setVisible(false)
        elseif choice == 1 or choice == #names then 
            saveState("SEARCH_MENU", "0")
            mainMenu()
        elseif choice == 2 or choice == #names - 1 then
            saveState("SEARCH_MENU", "0")
            searchByName()
        else 
            saveState("SEARCH_MENU", userInput .. "|" .. tostring(choice))
            local sel = matches[choice - 2]
            if sel.type == "U" then applyUnified(sel.data)
            elseif sel.type == "S" then applySkins(sel.data.item, sel.data.key) end
            gg.setVisible(false)
        end
    end
end


local cachedResults = nil
function finishEventMenu()
    local choice = gg.choice({"إنجاز الجزء الأول", "إنجاز الجزء الثاني", "⬅️ عودة"}, nil, "قائمة إنجاز الحدث")
    
    if choice == 1 then
        performFinish(1)
    elseif choice == 2 then
        performFinish(10000)
    elseif choice == 3 then
        expEventMenu()
    end
end

function performFinish(val)
    if not cachedResults or #cachedResults == 0 then
        gg.toast("❤️ صلي على النبي ❤️")
        gg.clearResults()
        gg.searchNumber("1886930200;1953064037;256::121", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
        gg.refineNumber("256", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
        cachedResults = gg.getResults(100)
    end
    
    if cachedResults and #cachedResults > 0 then
        local edits = {}
        local resultsToGet = gg.getValues(cachedResults)
        
        for i, v in ipairs(cachedResults) do
            local addr1 = v.address + 0xC
            local addr2 = v.address + 0xC - 4
            
            local val1 = gg.getValues({{address = addr1, flags = gg.TYPE_DWORD}})[1].value
            local val2 = gg.getValues({{address = addr2, flags = gg.TYPE_DWORD}})[1].value
            
            if val1 == 0 then
                table.insert(edits, {address = addr1, value = val, flags = gg.TYPE_DWORD})
            end
            
            if val2 == 0 then
                table.insert(edits, {address = addr2, value = val, flags = gg.TYPE_DWORD})
            end
        end
        
        if #edits > 0 then
            gg.setValues(edits)
            if val == 1 then
                gg.alert("تم إنجاز الجزء الأول بنجاح")
            else
                gg.alert("تم إنجاز الجزء الثاني بنجاح")
            end
        else
            gg.alert("حدث خطأ في إنجاز الحدث ⚠️")
        end
    else
        gg.alert("لم يتم العثور على نتائج")
        cachedResults = nil
    end
end

function changeEvent(currentId, targetId)
    local currentEv = eve_searchs["Event " .. currentId]
    local targetEv = eve_searchs["Event " .. targetId]

    if not currentEv or not targetEv then
        gg.alert("حدث غير موجود في الجدول، تأكد من الـ ID ف الإرشادات 📖")
        return
    end

    -- البحث الأول والصقل والتعديل للحدث الحالي
    gg.toast(" ❤️ صلي على النبي ❤️ ")
    gg.clearResults()
    gg.searchNumber(currentEv["code"][1], gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    gg.refineNumber(currentEv["refine"][1], gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    
    local res1 = gg.getResults(1000)
    for i, v in ipairs(res1) do
        v.value = 0
    end
    gg.setValues(res1)

    -- البحث الثاني والصقل والتعديل للحدث المستهدف
    
    gg.clearResults()
    gg.searchNumber(targetEv["code"][2], gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    gg.refineNumber(targetEv["refine"][2], gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    
    local res2 = gg.getResults(1)
    if #res2 > 0 then
        res2[1].value = 1782464400
        gg.setValues(res2)
    end
    gg.clearResults()
    gg.toast("تم تبديل الحدث بنجاح ✅️")
    saveState("EVENT_MENU", "0") 
    gg.setVisible(false)
end



function restartEvent()
    gg.toast("❤️ صلي على النبي ❤️")
    gg.clearResults()
    gg.searchNumber("1886930212;1953064037;1601073001::9", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    
