    end
    gg.clearResults()
end


function trim(s)
    return s:match("^%s*(.-)%s*$")
end


local cachedReceiveCardsResults = nil
function receiveCards()
    local userInput = gg.prompt(
        {"اكتب عدد أكياس الكروت الذهبية التي تريدها:"},
        nil,
        {"number"}
    )

    if not userInput or userInput[1] == "" then
        return
    end

    local targetVal = tonumber(userInput[1])
    if targetVal == nil then
        gg.alert("لم يتم إدخال عدد صحيح .. حاول مجدداً 😁")
        return
    end

    gg.toast("🇦 🇭 🇲 🇪 🇩")

    -- البحث يتم مرة واحدة فقط ويتم حفظ النتائج مؤقتاً
    if cachedReceiveCardsResults == nil then
        gg.clearResults()
        gg.searchNumber("65538;1;1;12546::113", 4)
        gg.refineNumber("65538", 4)

        local count = gg.getResultCount()
        if count == 0 then
            gg.alert("لم يتم العثور ع هدية رقم 1 في متجر سباق الزوارق ❌")
            gg.setVisible(true)
            return
        end
        cachedReceiveCardsResults = gg.getResults(count)
    end

    local editList = {}
    local freezeList = {}

    for _, r in ipairs(cachedReceiveCardsResults) do
        local baseAddress = r.address

        table.insert(editList, {address = baseAddress + 40, value = 1918976790, flags = 4})
        table.insert(editList, {address = baseAddress + 44, value = 1348420452, flags = 4})
        table.insert(editList, {address = baseAddress + 48, value = 896230241, flags = 4})
        table.insert(editList, {address = baseAddress + 52, value = 0, flags = 4})
        table.insert(editList, {address = baseAddress + 56, value = 0, flags = 4})
        table.insert(editList, {address = baseAddress + 60, value = 0, flags = 4})

        table.insert(freezeList, {address = baseAddress + 100, value = 0, flags = 4, freeze = true})

        table.insert(editList, {address = baseAddress + 76, value = 0, flags = 4})

        table.insert(editList, {address = baseAddress + 80, value = targetVal, flags = 4})

        table.insert(freezeList, {address = baseAddress + 84, value = 0, flags = 4, freeze = true})
        table.insert(freezeList, {address = baseAddress + 88, value = 0, flags = 4, freeze = true})
    end

    gg.setValues(editList)
    gg.addListItems(freezeList)

    gg.alert("اذهب الى متجر سباق الزوارق واضغط ع الهدية رقم 1 لاستلام اكياس الكروت الذهبية ✅️")
    gg.clearResults()
end


function upCards()
    gg.clearResults()
    gg.searchNumber("1918984974~1918984976;1~20::29", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    gg.refineNumber("1~20", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    
    local res = gg.getResults(1000)
    if #res == 0 then
       gg.alert("لم يتم العثور ع نتايج ❌️\n\nتأكد من وجود كروت بالفعل حتى يتم زيادتها ✅️\n\nأو تأكد من انك اخترت اللعبه قبل بدأ الاسكريبت ✅️")
    
        return
    end
    
    local prompt = gg.prompt({"اكتب العدد الذي تريده"}, {[1] = 1}, {"number"})
    if prompt == nil then return end
    
    local val = tonumber(prompt[1])
    for i, v in ipairs(res) do
        res[i].value = val
    end
    
    gg.setValues(res)
    gg.clearResults()
    gg.toast("تم زيادة عدد الكروت بنجاح ✅️")
    saveState("CARDS_MENU", "0")
    gg.setVisible(false)
end

function sendCards()
    if cardsEnabled then gg.alert("⚠️ إرسال الكروت مفعل بالفعل."); return end

    gg.toast("❤️ صلي على النبي ❤️")

    if cardsCached then
        local freezeItems, edit1, edit2 = {}, {}, {}

        for _, v in ipairs(cardsBackup.freezeItems) do table.insert(freezeItems, {address = v.address, flags = v.flags, value = 0, freeze = true}) end
        if #freezeItems > 0 then gg.setValues(freezeItems); gg.addListItems(freezeItems) end

        for _, v in ipairs(cardsBackup.values1) do table.insert(edit1, {address = v.address, flags = v.flags, value = 2003790951}) end
        if #edit1 > 0 then gg.setValues(edit1) end

        for _, v in ipairs(cardsBackup.values2) do table.insert(edit2, {address = v.address, flags = v.flags, value = 0}) end
        if #edit2 > 0 then gg.setValues(edit2) end

        cardsEnabled = true
        gg.alert("يمكنك الآن إرسال الكروت بنجاح ✅️\n\n⚠️ لا ترسل الكثير من الكروت دفعة واحدة، حتى لا تتعرض أنت ولمن ترسل له للحظر 🚫")
        saveState("CARDS_MENU", "0")
        gg.setVisible(false)
        return
    end

    cardsBackup = {freezeItems = {}, values1 = {}, values2 = {}}

    -- تجميد القيم
    gg.clearResults()
    gg.searchNumber("65535;3;86400::37", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
    gg.refineNumber("86400", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)

    local res = gg.getResults(1)

    if #res > 0 then
        local addr = res[1].address


        for i = 0, 5 do
            local item = {address = addr + 0x20 + (i * 4), flags = gg.TYPE_DWORD, value = 0, freeze = true}
            table.insert(cardsBackup.freezeItems, item)
            gg.setValues({item})
            gg.addListItems({item})
        end

        local extraItems = {}
        for i = 0, 3 do table.insert(extraItems, {address = addr + 80 + (i * 4), flags = gg.TYPE_DWORD, value = 0, freeze = true}) end

        for _, item in ipairs(extraItems) do table.insert(cardsBackup.freezeItems, item) end

        gg.setValues(extraItems)
        gg.addListItems(extraItems)
    end

    -- حفظ وإرسال المجموعة الأولى
    gg.clearResults()
    gg.searchNumber("4;1684828007;0;0::13", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)

    local res2 = gg.getResults(1000)

    for _, v in ipairs(res2) do
        if v.value == 1684828007 then
            table.insert(cardsBackup.values1, {address = v.address, flags = v.flags, value = v.value})
            v.value = 0
        end
    end

    if #res2 > 0 then gg.setValues(res2) end

    -- حفظ وإرسال المجموعة الثانية
    gg.clearResults()
    gg.searchNumber("1701274988;1918985326;121::9", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)

    local res3 = gg.getResults(100)

    for _, v in ipairs(res3) do
        table.insert(cardsBackup.values2, {address = v.address, flags = v.flags, value = v.value})
        v.value = 0
    end

    if #res3 > 0 then gg.setValues(res3) end

    cardsCached = true
    cardsEnabled = true

    gg.clearResults()
    gg.alert("يمكنك الآن إرسال الكروت بنجاح ✅️\n\n⚠️ لا ترسل الكثير من الكروت دفعة واحدة، حتى لا تتعرض أنت ولمن ترسل له للحظر 🚫")
    saveState("CARDS_MENU", "0")
    gg.setVisible(false)
end

function cancelSendCards()
    if not cardsEnabled then
        gg.alert("⚠️ لا توجد عملية إرسال كروت مفعلة.")
        return
    end

    gg.toast("⏳ جاري إلغاء إرسال الكروت...")

    -- إزالة جميع التجميدات المحفوظة
    if cardsBackup and cardsBackup.freezeItems and #cardsBackup.freezeItems > 0 then
        gg.removeListItems(cardsBackup.freezeItems)
    end

    -- استرجاع المجموعة الأولى
    if cardsBackup and cardsBackup.values1 and #cardsBackup.values1 > 0 then
        gg.setValues(cardsBackup.values1)
    end

    -- استرجاع المجموعة الثانية
    if cardsBackup and cardsBackup.values2 and #cardsBackup.values2 > 0 then
        gg.setValues(cardsBackup.values2)
    end

    -- إلغاء التفعيل مع الاحتفاظ بالكاش
    cardsEnabled = false

    gg.clearResults()
    gg.alert("✅ تم إلغاء إرسال الكروت بنجاح.")
    saveState("CARDS_MENU", "0")
    gg.setVisible(false)
end

function applyStars()
    local userInput = gg.prompt(
        {
            "⭐ اكتب عدد النجوم التي لديك حالياً في الحدث:",
            "🎁 اكتب عدد النجوم التي تريد وضعها:"
        },
        nil,
        {"number", "number"}
    )

    if not userInput or userInput[1] == "" or userInput[2] == "" then
        return
    end

    local currentStars = tonumber(userInput[1])
    local targetStars = tonumber(userInput[2])

    if currentStars == nil or currentStars == 0 then
        gg.alert("يجب أن يكون لديك نجوم بالفعل ❌\n(لا يمكن أن يكون العدد 0 أو فارغاً)")
        return
    end

    if targetStars == nil then
        gg.alert("لم يتم إدخال عدد صحيح .. حاول مجدداً 😁")
        return
    end

    gg.toast("🇦 🇭 🇲 🇪 🇩")
    gg.clearResults()
    
    local searchQuery = "256;" .. currentStars .. ";0;" .. currentStars .. "::101"
    gg.searchNumber(searchQuery, 4)

    local refineQuery1 = currentStars .. ";0;" .. currentStars .. "::9"
    gg.refineNumber(refineQuery1, 4)

    gg.refineNumber("0", 4)

    local resultsCount = gg.getResultCount()
    
    if resultsCount == 1 then
        local res = gg.getResults(1)
        local baseAddress = res[1].address

        local editList = {
            {address = baseAddress - 8, value = targetStars, flags = 4},
            {address = baseAddress - 4, value = targetStars, flags = 4},
            {address = baseAddress + 4, value = targetStars, flags = 4}
        }

        gg.setValues(editList)
        gg.clearResults()
        gg.toast("تم تعديل عدد النجوم بنجاح ✅️")

    elseif resultsCount > 1 then
        local allResults = gg.getResults(resultsCount)
        local validAddress = nil

        for _, r in ipairs(allResults) do
            local checkVal = gg.getValues({{address = r.address + 144, flags = 4}})
            if checkVal and checkVal[1] and checkVal[1].value == 3 then
                validAddress = r.address
                break
            end
        end

        if validAddress then
            local editList = {
                {address = validAddress - 8, value = targetStars, flags = 4},
                {address = validAddress - 4, value = targetStars, flags = 4},
                {address = validAddress + 4, value = targetStars, flags = 4}
            }

            gg.setValues(editList)
            gg.clearResults()
            gg.toast("تم تعديل عدد النجوم بنجاح ✅️")
        else
            gg.alert("❌ لم يتم العثور على النتيجة الصحيحة من ضمن النتائج المتعددة.\n\nتأكد من نطاقات الذاكرة، واغلق اللعبة واعد تشغيلها.")
            gg.setVisible(true)
        end

    else
        gg.alert("❌ لم يتم العثور على النتيجة.\n\nتأكد من نطاقات الذاكرة، واغلق اللعبة واعد تشغيلها.")
        gg.setVisible(true)
    end
end



