function applyBreak(selectedItems)
    local confirm = gg.alert("سيتم تنفيذ المهام المحددة، هل تريد الإكمال؟", "نعم", "لا")
    
    if confirm == 1 then
        for _, item in ipairs(selectedItems) do
            processBreak(item)
        end
    else
        gg.setVisible(true)
        return
    end
    gg.setVisible(false)
end

function processBreak(item)
    gg.clearResults()
    gg.searchNumber(item.Code, 4)
    gg.refineNumber(item.refine, 4)
    
    local count = gg.getResultsCount()
    if count == 0 then return end
    
    local results = gg.getResults(count)
    local editList = {}
    
    for _, r in ipairs(results) do
        table.insert(editList, {address = r.address + 36, value = 0, flags = 4})
        table.insert(editList, {address = r.address + 40, value = 50000, flags = 4})
    end    
    gg.setValues(editList)    
    gg.toast("تم إنجاز مهمة " .. item.name .. " بنجاح 🥰✅️")
end

