function upMatch3()
    local userInput = gg.prompt(
        {
            "🎯 اكتب مستوى المطابقة الحالي:",
            "🚀 اكتب مستوى المطابقة الذي تريده:"
        },
        nil,
        {"number", "number"}
    )

    if not userInput or userInput[1] == "" or userInput[2] == "" then
        return
    end

    local currentMatch = tonumber(userInput[1])
    local targetMatch = tonumber(userInput[2])

    if currentMatch == nil or targetMatch == nil then
        gg.alert("لم يتم إدخال عدد صحيح .. حاول مجدداً 😁")
        return
    end

    gg.toast("🇦 🇭 🇲 🇪 🇩")
    gg.clearResults()

    local searchQuery = "65537;-1;" .. currentMatch .. ";2::217"
    gg.searchNumber(searchQuery, 4)

    gg.refineNumber("2", 4)

    local resultsCount = gg.getResultCount()
    local targetAddress = nil

    if resultsCount == 1 then
        local res = gg.getResults(1)
        targetAddress = res[1].address
    elseif resultsCount > 1 then
        local allResults = gg.getResults(resultsCount)
        for _, r in ipairs(allResults) do
            local checkVal = gg.getValues({{address = r.address - 4, flags = 4}})
            if checkVal and checkVal[1] then
                local val = checkVal[1].value
                if val == currentMatch  then
                    targetAddress = r.address
                    break
                end
            end
        end
    end

    if targetAddress then
        local editList = {
            {address = targetAddress - 4, value = targetMatch, flags = 4}
        }
        gg.setValues(editList)
        gg.clearResults()
        gg.alert("✅ تم تعديل مستوى المطابقة بنجاح\n\n🎯 اذهب وقم بإنجاز مستوى حتى يتم تثبيت التغييرات.")
    else
        gg.alert("❌ لم يتم العثور على النتيجة.\n\nتأكد من نطاقات الذاكرة، واغلق اللعبة واعد تشغيلها.")
        gg.setVisible(true)
    end
end


