            {address = addr + 32, flags = gg.TYPE_DWORD, value = 0},
            {address = addr + 36, flags = gg.TYPE_DWORD, value = stageLevel}
        })

        gg.toast("تم الوصول للمرحلة بنجاح ✅️")
