function applyResource(item, sectionIndex, currentChoice)
    if item.name == "💰 زيادة الفلوس" then
        gg.alert([[
💰 زيــادة الـفـلـوس الـذهـبـيـة 💰

📌 بعد استلام الهدية:
• افتح مخزن الزينات.
• قم ببيع "الكاتب الأول".
• ستحصل على الفلوس الذهبية.

🌹 بالتوفيق.
]])
    end
    
    local promptMessage = "ما العدد الذي تريده :"
    if item.name == "⏰ معزز ديناميت بوقت (معزز خارجي)"
    or item.name == "⏰ معزز متفجر خط بوقت(معزز خارجي)"
    or item.name == "⏰ معزز كرة ديسكو بوقت(معزز خارجي)" 
    or item.name == "❤️ قلوب المطابقة بوقت" 
    or item.name == "✌🏻 المضاعف الاصفر( ×2)" then

    promptMessage = [[
⏱️ اكتب وقت المعزز الذي تريده (بالثواني)                                      

📌 أمثلة:                                      
• 86400 = يوم واحد                                     
• 8640000 = 100 يوم                                     
    ]]   
    end
    if item.name == "🏕️ زيادة حجم الشونة المؤقت" then
        promptMessage = [[ اكتب عدد اكتر من سعة الشونة عندك ]]
    end
    if item.name == "⏰️ تقليل وقت البناء"
    or item.name == "⏰️ تقليل وقت الزراعة"
    or item.name == "⏰️ تقليل وقت انتاج مزارع الحيوانات"
    or item.name == "⏰️ تقليل وقت رجوع الطائرة"then
    promptMessage = [[
⏱️ اكتب نسبة تقليل الوقت التي تريدها (%)                                      

📌 أمثلة:                                         
• 100 = إنهاء الوقت بالكامل ماعدا وقت الطائرة اكتب 99                                         
• 50 =  تقليل الوقت إلى النصف                                         
• 25 = تقليل الوقت بنسبة 25%                                         
]]
    end
 

    local countVal

-- قسم الملصقات لا يحتاج إدخال قيمة
local countVal

if resources[sectionIndex].section == "🎭 الملصقات 🎭"
or resources[sectionIndex].section == "🖼️ الصور 📸" then

    countVal = 1

else
    local userInput = gg.prompt({promptMessage}, nil, {"number"})
    if not userInput then
        return
    end

    countVal = tonumber(userInput[1])
    if userInput[1] == "" or countVal == nil then
        gg.alert("لم يتم إدخال عدد .. حاول مجدداً 😁")
        return
    end
end

    if unique_cachedGiftResults == nil then
        gg.toast("🇦 🇭 🇲 🇪 🇩")
        gg.clearResults()
        gg.searchNumber("65538;1;1;12546::113", 4)
        gg.refineNumber("65538", 4)
        unique_cachedGiftResults = gg.getResults(gg.getResultCount())
        
        if #unique_cachedGiftResults == 0 then 
            gg.alert("لم يتم العثور على الهدية 29!") 
            gg.setVisible(true)
            return 
        end
    end

    if item.isPointer then
        if unique_tableA == nil then
            gg.clearResults()
            gg.searchNumber("1768641320;1918132078;1601071457;1768058738;33;27::57", 4)
            gg.refineNumber("33", 4)
            local res = gg.getResults(1)
            if #res == 0 then gg.alert("لم يتم العثور ع كود استبدال المؤشر") gg.setVisible(true) return end
            unique_tableA = {}
            for i = 0, 5 do table.insert(unique_tableA, gg.getValues({{address = res[1].address + (i * 4), flags = 4}})[1].value) end
        end

        if unique_cachedPointerResults == nil then
            unique_cachedPointerResults = loadPointerResults()
        end
        
        if unique_cachedPointerResults == nil then         
            gg.clearResults()
            gg.searchNumber("1852402515;1634882655;1951624809;1869182049;1869766510;1215195490;6582127::25", 4)
            gg.refineNumber("1852402515", 4)
            local count = gg.getResultCount()
            if count == 0 then gg.alert("لم يتم العثور ع المؤشر الاساسي") gg.setVisible(true) return end
            unique_cachedPointerResults = gg.getResults(count)
            savePointerResults(unique_cachedPointerResults)
        end

        local unique_editList, unique_freezeList = {}, {}
        for _, r in ipairs(unique_cachedGiftResults) do
            table.insert(unique_freezeList, {address = r.address + 100, value = 0, flags = 4, freeze = true})
            table.insert(unique_freezeList, {address = r.address + 84, value = 0, flags = 4, freeze = true})
            table.insert(unique_freezeList, {address = r.address + 88, value = 0, flags = 4, freeze = true})
            for i = 0, 5 do table.insert(unique_editList, {address = r.address + 40 + (i * 4), value = unique_tableA[i+1], flags = 4}) end
            table.insert(unique_editList, {address = r.address + 48, value = item.Level, flags = 4})
            table.insert(unique_editList, {address = r.address + 76, value = 0, flags = 4})
            table.insert(unique_editList, {address = r.address + 80, value = countVal, flags = 4})
        end

        local codeCount = #item.Code
        for _, ptr in ipairs(unique_cachedPointerResults) do
            for i = 0, codeCount - 1 do
                table.insert(unique_editList, {
                    address = ptr.address + (i * 4), 
                    value = item.Code[i+1], 
                    flags = 4
                })
            end
        end
        
        gg.setValues(unique_editList)
        gg.addListItems(unique_freezeList)
        gg.alert("تم الاستبدال بنجاح ✅️\n\nاذهب واضغط ع الهدية 29 🎁")

    else
        local unique_editList, unique_freezeList = {}, {}
        for _, r in ipairs(unique_cachedGiftResults) do
                table.insert(unique_freezeList, {address = r.address + 100, value = 0, flags = 4, freeze = true})
                table.insert(unique_freezeList, {address = r.address + 84, value = 0, flags = 4, freeze = true})
                table.insert(unique_freezeList, {address = r.address + 88, value = 0, flags = 4, freeze = true})
                for j, h in ipairs(item.Code) do table.insert(unique_editList, {address = r.address + 36 + (j * 4), value = h, flags = 4}) end
                table.insert(unique_editList, {address = r.address + 76, value = 0, flags = 4})
                table.insert(unique_editList, {address = r.address + 80, value = countVal, flags = 4})
            
        end
        gg.setValues(unique_editList)
        gg.addListItems(unique_freezeList)
        gg.alert("تم الاستبدال بنجاح ✅️\n\nاذهب واضغط ع الهدية 29 🎁")
    end
    saveState("RES_SUB_MENU", tostring(sectionIndex) .. "|" .. tostring(currentChoice))
    gg.setVisible(false)
end


