function applyRequest(item, currentChoice)
    gg.toast("🇦 🇭 🇲 🇪 🇩")

    if cachedTrainResults == nil then
        gg.clearResults()
        gg.searchNumber("1801519104;49::13", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
        gg.refineNumber("49", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)

        cachedTrainResults = gg.getResults(100)

        if #cachedTrainResults == 0 then
            cachedTrainResults = nil
            gg.alert("لا يوجد نتايج ❌️\nابحث وانت فاتح القطار ، لو مطلعش نتايج ، ادخل الرحلة الاستكشافيه واخرج تاني ، بعدين افتح القطار وابحث✅️")
            return
        end
    end

    local res = cachedTrainResults

    local productMsg = "أدخل عدد منتج الطلب:"

    if item.name == "تاج" then
        productMsg = "👑 أدخل عدد منتج الطلب\n(أقصى عدد هو 40) (1-40):"
    end

    -- إدخال عدد المنتج
    local input = gg.prompt(
        {productMsg},
        {"1"},
        {"number"}
    )

    if not input then
        return
    end

    local userVal = tonumber(input[1])

    if item.name == "تاج" then
        if userVal < 1 or userVal > 40 then
            gg.alert("❌ عند اختيار التاج يجب أن يكون العدد بين 1 و40 فقط.")
            return
        end
    end

    -- تجهيز خيارات القطارات حسب عدد النتائج
    local trainChoices = {}

    if #res >= 1 then
        table.insert(trainChoices, "🚂 القطار الأول")
    end

    if #res >= 2 then
        table.insert(trainChoices, "🚂 القطار الثاني")
    end

    if #res >= 3 then
        table.insert(trainChoices, "🚂 القطار الثالث")
    end

    table.insert(trainChoices, "🚂 جميع القطارات")

    -- اختيار القطارات
    local choice = gg.multiChoice(
        trainChoices,
        nil,
        "اختر القطار أو القطارات التي تريد تعديل الطلب فيها"
    )

    if not choice then
        return
    end

    local indexes = {}

    -- جميع القطارات
    local allIndex = #trainChoices

    if choice[allIndex] then
        for i = 1, math.min(#res, 3) do
            table.insert(indexes, i)
        end
    else
        for i = 1, math.min(#res, 3) do
            if choice[i] then
                table.insert(indexes, i)
            end
        end
    end

    if #indexes == 0 then
        gg.alert("❌ اختر قطارًا واحدًا على الأقل.")
        return
    end

    local t = {}

    local function addBaseValues(base, uVal)
        for i = 0, 11 do
            table.insert(t, {
                address = base + 232 + (i * 4),
                value = 0,
                flags = gg.TYPE_DWORD,
                freeze = true
            })
        end

        table.insert(t, {address = base, value = item.Code[1], flags = gg.TYPE_DWORD, freeze = true})
        table.insert(t, {address = base + 4, value = item.Code[2], flags = gg.TYPE_DWORD, freeze = true})
        table.insert(t, {address = base + 8, value = item.Code[3], flags = gg.TYPE_DWORD, freeze = true})
        table.insert(t, {address = base + 12, value = item.Code[4], flags = gg.TYPE_DWORD, freeze = true})
        table.insert(t, {address = base + 16, value = item.Code[5], flags = gg.TYPE_DWORD, freeze = true})
        table.insert(t, {address = base + 20, value = item.Code[6], flags = gg.TYPE_DWORD, freeze = true})

        table.insert(t, {address = base + 24, value = 0, flags = gg.TYPE_DWORD, freeze = true})
        table.insert(t, {address = base + 28, value = uVal, flags = gg.TYPE_DWORD, freeze = true})
        table.insert(t, {address = base + 72, value = 1, flags = gg.TYPE_DWORD, freeze = true})
    end

    local function addZeroBlock(base)
        local addr = base + 304

        for i = 0, 40 do
            table.insert(t, {
                address = addr + (i * 4),
                value = 0,
                flags = gg.TYPE_DWORD,
                freeze = true
            })
        end
    end

    for _, i in ipairs(indexes) do
        local v = res[i]

        local base1 = v.address - 0x15C
        local base2 = base1 - 0x130
        local base3 = base2 - 0x130
        local base4 = base3 - 0x130
        local base5 = base4 - 0x130

        addBaseValues(base1, userVal)
        addBaseValues(base2, userVal)
        addBaseValues(base3, userVal)
        addBaseValues(base4, userVal)
        addBaseValues(base5, userVal)
        addZeroBlock(base1)
    end

    gg.setValues(t)

    local freezeList = {}

    for _, v in ipairs(t) do
        if v.freeze then
            table.insert(freezeList, v)
        end
    end

    gg.addListItems(freezeList)
    gg.clearResults()
    saveState("ORDER_MENU", tostring(currentChoice))
    gg.toast("✅ تم تعديل طلب " .. item.name .. " بنجاح")
    gg.setVisible(false)
end

function applyFreezeClover()
    gg.toast("🇦 🇭 🇲 🇪 🇩")

    -- حذف أي تجميد قديم
    if #cloverFreezeItems > 0 then
        gg.removeListItems(cloverFreezeItems)
        cloverFreezeItems = {}
    end

    -- البحث لأول مرة فقط
    if cachedTrainResults == nil then
        gg.clearResults()
        gg.searchNumber("1801519104;49::13", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
        gg.refineNumber("49", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)

        cachedTrainResults = gg.getResults(100)

        if #cachedTrainResults == 0 then
            cachedTrainResults = nil
            gg.alert("لا يوجد نتايج ❌️\nابحث وانت فاتح القطار، ولو مطلعش نتايج ادخل الرحلة الاستكشافية واخرج منها ثم افتح القطار وابحث مرة أخرى ✅️")
            return
        end
    end

    local res = cachedTrainResults

    local choice = gg.multiChoice(
        {
            "🚂 القطار الأول",
            "🚂 القطار الثاني",
            "🚂 القطار الثالث",
            "🚂 جميع القطارات"
        },
        nil,
        "اختر القطار أو القطارات التي تريد تجميد إرسال البرسيم فيها"
    )

    if not choice then
        return
    end

    local indexes = {}

    if choice[4] then
        indexes = {1, 2, 3}
    else
        if choice[1] then table.insert(indexes, 1) end
        if choice[2] then table.insert(indexes, 2) end
        if choice[3] then table.insert(indexes, 3) end
    end

    if #indexes == 0 then
        gg.alert("❌ اختر قطارًا واحدًا على الأقل.")
        return
    end

    if #res < 3 then
        gg.alert("❌ لا توجد نتائج كافية.")
        return
    end

    local t = {}
    cloverFreezeItems = {}

    for _, i in ipairs(indexes) do
        local v = res[i]

        local base1 = v.address - 0x15C
        local base2 = base1 - 0x130
        local base3 = base2 - 0x130
        local base4 = base3 - 0x130
        local base5 = base4 - 0x130

        local items = {
            {address = base1 + 192, value = 0, flags = gg.TYPE_DWORD, freeze = true},
            {address = base2 + 192, value = 0, flags = gg.TYPE_DWORD, freeze = true},
            {address = base3 + 192, value = 0, flags = gg.TYPE_DWORD, freeze = true},
            {address = base4 + 192, value = 0, flags = gg.TYPE_DWORD, freeze = true},
            {address = base5 + 192, value = 0, flags = gg.TYPE_DWORD, freeze = true}
        }

        for _, item in ipairs(items) do
            table.insert(t, item)
            table.insert(cloverFreezeItems, item)
        end
    end

    gg.setValues(t)
    gg.addListItems(t)

    cloverEnabled = true

    gg.clearResults()
    gg.toast("✅ تم تجميد إرسال البرسيم")
    gg.setVisible(false)
end


function applyClover()
    gg.toast("🇦 🇭 🇲 🇪 🇩")

    -- البحث لأول مرة فقط
    if cachedTrainResults == nil then
        gg.clearResults()
        gg.searchNumber("1801519104;49::13", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)
        gg.refineNumber("49", gg.TYPE_DWORD, false, gg.SIGN_EQUAL, 0, -1)

        cachedTrainResults = gg.getResults(100)

        if #cachedTrainResults == 0 then
            cachedTrainResults = nil
            gg.alert("لا يوجد نتايج ❌️\nابحث وانت فاتح القطار ، لو مطلعش نتايج ، ادخل الرحلة الاستكشافيه واخرج تاني ، بعدين افتح القطار وابحث✅️")
            return
        end
    end

    local res = cachedTrainResults

    -- إدخال كود اللاعب
    local input = gg.prompt(
        {"📨 قم بوضع كود اللاعب الذي تريد الإرسال إليه\n(مثال: 123,456,789)"},
        {""},
        {"text"}
    )

    if not input then
        return
    end

    local text = input[1]:gsub(";", ",")
    local code1, code2, code3 = text:match("^(%-?%d+),(%-?%d+),(%-?%d+)$")

    if not code1 then
        gg.alert("❌ صيغة الكود غير صحيحة.")
        return
    end

    code1, code2, code3 = tonumber(code1), tonumber(code2), tonumber(code3)

    -- اختيار القطارات
    local choice = gg.multiChoice(
        {
            "🚂 القطار الأول",
            "🚂 القطار الثاني",
            "🚂 القطار الثالث",
            "🚂 جميع القطارات"
        },
        nil,
        "اختر القطار أو القطارات التي تريد إرسال البرسيم إليها"
    )

    if not choice then
        return
    end

    local indexes = {}

    if choice[4] then
        indexes = {1, 2, 3}
    else
        if choice[1] then table.insert(indexes, 1) end
        if choice[2] then table.insert(indexes, 2) end
        if choice[3] then table.insert(indexes, 3) end
    end

    if #indexes == 0 then
        gg.alert("❌ اختر قطارًا واحدًا على الأقل.")
        return
    end

    if #res < 3 then
        gg.alert("❌ لا توجد نتائج كافية.")
        return
    end

    local t = {}

    -- لا نحذف cloverFreezeItems القديمة
    if cloverFreezeItems == nil then
        cloverFreezeItems = {}
    end

    local function addBaseValues(base)
        table.insert(t, {address = base, value = 1701345034, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 4, value = 29793, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 8, value = 0, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 12, value = 0, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 16, value = 0, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 20, value = 0, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 40, value = 1, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 72, value = 1, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 80, value = code1, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 84, value = code2, flags = gg.TYPE_DWORD})
        table.insert(t, {address = base + 88, value = code3, flags = gg.TYPE_DWORD})

        local freezeItem = {
            address = base + 192,
            value = 0,
            flags = gg.TYPE_DWORD,
            freeze = true
        }

        table.insert(t, freezeItem)
        table.insert(cloverFreezeItems, freezeItem)
    end

    for _, i in ipairs(indexes) do
        local v = res[i]
        local base = v.address - 0x15C

        addBaseValues(base)
        addBaseValues(base - 0x130)
        addBaseValues(base - (0x130 * 2))
        addBaseValues(base - (0x130 * 3))
        addBaseValues(base - (0x130 * 4))
    end

    gg.setValues(t)
    gg.addListItems(cloverFreezeItems)

    cloverEnabled = true

    gg.clearResults()
    gg.toast("✅ تم تعبئة وإرسال البرسيم بنجاح")
    gg.setVisible(false)
end

function cancelFreezeClover()
    if not cloverEnabled then
        gg.alert("⚠️ لا يوجد تجميد لإرسال البرسيم.")
        return
    end

    gg.toast("⏳ جاري إلغاء تجميد إرسال البرسيم...")

    if #cloverFreezeItems > 0 then
        gg.removeListItems(cloverFreezeItems)
    end

    cloverEnabled = false

    gg.clearResults()
    gg.alert("✅ تم إلغاء تجميد إرسال البرسيم بنجاح.")
    gg.setVisible(false)
end

function findCode()
    local input = gg.prompt(
        {
            "ما مستوى المدينة أو المدى\n(مثال: 120 أو 100~200)"
        },
        {""},
        {"text"}
    )

    if not input then
        return
    end

    local levelInput = input[1]
    local rankInput = "1~4"

    -- التحقق من المستوى
    if not levelInput:match("^%d+$") and not levelInput:match("^%d+~%d+$") then
        gg.alert("⚠️ أدخل مستوى صحيح أو مدى مثل 100~200.")
        return
    end

    gg.toast("❤️ صلي على النبي ❤️")
    gg.clearResults()

    local searchQuery = rankInput .. ";" .. levelInput .. ";500~550;0;500~540::29"
    gg.searchNumber(searchQuery, gg.TYPE_DWORD)

    -- الصقل على الرتبة فقط
    gg.refineNumber(rankInput, gg.TYPE_DWORD)

    local results = gg.getResults(1000)

    if #results == 0 then
        gg.alert(
            "⚠️ تأكد من ضبط نطاقات الذاكرة.\n\n" ..
            "🔗 وتأكد بأن اللاعب الذي تريد استخراج كوده موجود في التعاون."
        )
        return
    end

    local function dwordToText(d1, d2, d3)
        local bytes = {}

        for _, v in ipairs({d1, d2, d3}) do
            for i = 0, 3 do
                local b = (v >> (8 * i)) & 0xFF
                if b == 0 then
                    return string.char(table.unpack(bytes))
                end
                if b ~= 0x14 then
                    table.insert(bytes, b)
                end
            end
        end

        return string.char(table.unpack(bytes))
    end

    local selectedResult

    if #results == 1 then
        selectedResult = results[1]
    else
        local menu = {}

        for i, v in ipairs(results) do
            local utf = gg.getValues({
                {address = v.address - 64, flags = gg.TYPE_DWORD},
                {address = v.address - 60, flags = gg.TYPE_DWORD},
                {address = v.address - 56, flags = gg.TYPE_DWORD}
            })

            local name = dwordToText(
                utf[1].value,
                utf[2].value,
                utf[3].value
            )

            menu[i] = "👤 " .. name
        end

        local choice = gg.choice(
            menu,
            nil,
            "تم العثور على " .. #results .. " نتائج\nاختر اللاعب المطلوب"
        )

        if not choice then
            gg.clearResults()
            return
        end

        selectedResult = results[choice]
    end

    local utf = gg.getValues({
        {address = selectedResult.address - 64, flags = gg.TYPE_DWORD},
        {address = selectedResult.address - 60, flags = gg.TYPE_DWORD},
        {address = selectedResult.address - 56, flags = gg.TYPE_DWORD}
    })

    local playerName = dwordToText(
        utf[1].value,
        utf[2].value,
        utf[3].value
    )

    local targetAddress = selectedResult.address - 136

    local values = gg.getValues({
        {address = targetAddress, flags = gg.TYPE_DWORD},
        {address = targetAddress + 4, flags = gg.TYPE_DWORD},
        {address = targetAddress + 8, flags = gg.TYPE_DWORD}
    })

    local copiedCode = values[1].value .. ";" .. values[2].value .. ";" .. values[3].value

    gg.copyText(copiedCode)

    gg.alert(
        "✅ تم نسخ كود اللاعب في الحافظة.\n\n" ..
        "👤 اسم اللاعب:\n" .. playerName
    )

    gg.clearResults()
    gg.setVisible(false)
end

function applyAddFriend()
    local password = gg.prompt({"🔐 اكتب كلمة السر:"}, {""}, {"text"})
    
    if not password or password[1] ~= "Admin" then
        gg.alert("❌ كلمة السر غير صحيحة!")
        return
    end

    local promptMsg = gg.choice({"حسنا", "إلغاء"}, nil, "قبل بدء اضافه صديق عليك ارسال صداقه اولا لهذا الصديق حتى يتم اضافته ، هل تريدي الإكمال")
    if promptMsg ~= 1 then
        friendsMenu()
        return
    end

    -- البحث مرة واحدة فقط
    if not cachedAddFriendResults then
        gg.clearResults()
        gg.searchNumber("300000000;300;300000000;3000000::41", gg.TYPE_DWORD)
        gg.refineNumber("3000000", gg.TYPE_DWORD)

        local results = gg.getResults(100)

        if #results == 0 then
            gg.alert("يضبط نطاقات الذاكرة")
            return
        end

        cachedAddFriendResults = results
    end

    -- استخدام النتائج المحفوظة بدون بحث جديد
    local results = cachedAddFriendResults

    local t = {}

    for i, v in ipairs(results) do
        local sourceValues = {}

        for j = 0, 5 do
            local res = gg.getValues({
                {
                    address = v.address + 360 + (j * 4),
                    flags = gg.TYPE_DWORD
                }
            })

            if res[1] then
                table.insert(sourceValues, res[1].value)
            else
                table.insert(sourceValues, 0)
            end
        end

        for j = 0, 5 do
            table.insert(t, {
                address = v.address + 112 + (j * 4),
                flags = gg.TYPE_DWORD,
                value = sourceValues[j + 1],
                freeze = false
            })
        end
    end

    gg.setValues(t)
    gg.addListItems(t)
    gg.clearResults()
    gg.toast("تم اضافه الاصدقاء بنجاح ✅️")
    gg.setVisible(false)
end

