━━━━━━━━━━━━━━━━━━
]])
            gg.setVisible(true)
            return
        end

        clanAchievementsResults = gg.getResults(count)
        clanAchievementsCached = true
        gg.clearResults()
    end

    local allResults = clanAchievementsResults

    local menuOptions = {
        "🏆 الصديق وقت الضيق",
        "🏆 الجائزة الكبرى",
        "🏆 توصيل سريع",
        "🏆 حمولة ثقيلة",
        "🏆 سادة البحر",
        "🏆 هدف مشترك",
        "🏆 منقبون دؤوبون",
        "🏆 إنتاج مستمر",
        "🏆 زعماء اللعبة",
        "🏆 فائزون بالفطرة",
        "🏆 دوري الدرجة الأولى",
        "🏆 جميع الإنجازات"
    }

    local choices = gg.multiChoice(
        menuOptions,
        nil,
        "🏆 إنجازات التعاون\n\nحدد الإنجازات التي تريد تعديلها:"
    )
    
    if not choices then
        return
    end

    local editList = {}

    local function checkAndAdd(targetVal)
        for _, r in ipairs(allResults) do
            local valObj = gg.getValues({
                {address = r.address + 20, flags = gg.TYPE_DWORD}
            })

            if valObj and valObj[1] and valObj[1].value == targetVal then
                table.insert(editList, {
                    address = r.address + 20,
                    value = 1,
                    flags = gg.TYPE_DWORD
                })
            end
        end
    end

    local selectedAny = false

    if choices[12] then
        checkAndAdd(10000)
        checkAndAdd(5000)
        checkAndAdd(500)
        checkAndAdd(400)
        checkAndAdd(1000)
        checkAndAdd(300)
        checkAndAdd(20)
        checkAndAdd(1)
        selectedAny = true
    else
        if choices[1] then checkAndAdd(10000); selectedAny = true end
        if choices[2] then checkAndAdd(5000); selectedAny = true end
        if choices[3] then checkAndAdd(500); selectedAny = true end
        if choices[4] then checkAndAdd(500); selectedAny = true end
        if choices[5] then checkAndAdd(400); selectedAny = true end
        if choices[6] then checkAndAdd(1000); selectedAny = true end
        if choices[7] then checkAndAdd(400); selectedAny = true end
        if choices[8] then checkAndAdd(300); selectedAny = true end
        if choices[9] then checkAndAdd(500); selectedAny = true end
        if choices[10] then checkAndAdd(20); selectedAny = true end
        if choices[11] then checkAndAdd(1); selectedAny = true end
    end

    if not selectedAny then
        gg.alert("⚠️ لم يتم اختيار أي إنجاز.\n\nيرجى اختيار إنجاز واحد على الأقل.")
        return
    end

    if #editList > 0 then
        gg.setValues(editList)
        gg.clearResults()
        gg.alert([[🏆 تم تعديل الإنجازات بنجاح! ✅️

📌 قم بتنفيذ الخطوات التالية بالترتيب:

1️⃣ حقق مهمة واحدة على الأقل من الإنجاز المعدّل.
2️⃣ غيّر لغة اللعبة للغة أخرى.
3️⃣ أغلق اللعبة بالكامل وأعد تشغيلها.
4️⃣ افتح اللعبة وتحقق من الإنجازات. 🎉]])
    else
        gg.alert([[
