function applyChatWheat()
    local userInput = gg.prompt(
        {"🌾 اكتب كمية القمح التي تريدها:"},
        nil,
        {"number"}
    )

    if not userInput or userInput[1] == "" then
        return
    end

    local targetVal = tonumber(userInput[1])

    if targetVal == nil or targetVal <= 0 then
        gg.alert("يجب أن تكون القيمة أكبر من 0 .. حاول مجدداً ❌")
        return
    end

    gg.toast("🇦 🇭 🇲 🇪 🇩")
    gg.clearResults()

    gg.searchNumber("1701147414;1701345046;1::109", 4)
    gg.refineNumber("1701345046", 4)

    local resultsCount = gg.getResultCount()

    if resultsCount > 0 then
        local res = gg.getResults(1)
        local baseAddress = res[1].address

        local editList = {
            {address = baseAddress + 208, value = 0, flags = 4},
            {address = baseAddress + 212, value = targetVal, flags = 4}
        }

        gg.setValues(editList)
        gg.clearResults()
        gg.toast("تم التعديل بنجاح ✅️")
    else
        gg.alert("❌ لم يتم العثور على نتائج.\n\nاظبط النطاقات ، واغلق اللعبة واعد تشغيلها.")
        gg.setVisible(true)
    end
end

