function orderMenu(defaultChoice)
    local currentChoice = tonumber(defaultChoice) or 1
    saveState("ORDER_MENU", tostring(currentChoice))

    local choices = {
        "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"
    }

    for _, item in ipairs(products) do
        table.insert(choices, "📦 " .. item.name)
    end

    table.insert(choices, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")

    local choice = gg.choice(choices, currentChoice, "🚂 طلب القطار")

    if choice == nil then
        gg.setVisible(false)

    elseif choice == 1 or choice == #choices then
        saveState("ORDER_MENU", "0")
        friendsMenu()

    else
        saveState("ORDER_MENU", tostring(choice))
        local item = products[choice - 1]
        applyRequest(item, choice)
        gg.setVisible(false)
    end
end


