function resSubMenu(sectionIndex, defaultChoice)
    local currentChoice = tonumber(defaultChoice) or 1
    saveState("RES_SUB_MENU", tostring(sectionIndex) .. "|" .. tostring(currentChoice))

    local section = resources[sectionIndex]

    local choices = {
        "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"
    }

    for _, item in ipairs(section.items) do
        table.insert(choices, " " .. item.name)
    end

    table.insert(choices, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")

    local choice = gg.choice(choices, currentChoice, "📦 " .. section.section)

    if choice == nil then
        gg.setVisible(false)

    elseif choice == 1 or choice == #choices then
        saveState("RES_SUB_MENU", "0")
        resMainMenu()

    else
        saveState("RES_SUB_MENU", tostring(sectionIndex) .. "|" .. tostring(choice))
        local item = section.items[choice - 1]
        applyResource(item, sectionIndex, choice)
        gg.setVisible(false)
    end
end

function resMainMenu()
    saveState("RES_MAIN_MENU", "0")

    local menu = {
        "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"
    }

    for i, v in ipairs(resources) do
        table.insert(menu, " " .. v.section)
    end

    table.insert(menu, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")

    local choice = gg.choice(menu, nil, "📦 مــــوارد الـمــــديــــنــــة 📦")

    if choice == nil then
        return
    elseif choice == 1 or choice == #menu then
        mainMenu()
    else
        local sectionIndex = choice - 1

        -- رسالة قسم الملصقات
        if resources[sectionIndex].section == "🎭 الملصقات 🎭" then
            gg.alert([[
🎭 الملصقات

📌 بعد استلام الهدية ثم استلام الملصق:

• أغلق اللعبة بالكامل.
• ثم افتحها مرة أخرى.

✅ بعد إعادة تشغيل اللعبة ستظهر الملصقات الجديدة.
]])
        end

        resSubMenu(sectionIndex, 1)
    end
end

function breakMenu()
    saveState("BREAK_MENU", "0")

    local choices = {
        "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"
    }
    
    for _, v in ipairs(bre_event) do
        table.insert(choices, v.name)
    end
    table.insert(choices, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")

    local selected = gg.multiChoice(choices, nil, "🏷 قائمة مهام الحدث ")

    if not selected then
        saveState("BREAK_MENU", "0")
        return
    end

    local itemsToProcess = {}
    for i, v in pairs(selected) do
        if v then
            if i == 1 or i == #choices then
                eventsMenu()
                return
            end
            table.insert(itemsToProcess, bre_event[i - 1])
        end
    end

    if #itemsToProcess > 0 then
        applyBreak(itemsToProcess)
    end
end


