function skinsMenu(typeKey, defaultChoice)
    local keys = {"TRAIN", "HELICOPTER", "PLANE", "TRAIN_STATION", "HELICOPTER_PAD", "AIRPORT", "SHIP", "PORT", "COW", "CHICKEN", "SHEEP", "PIG", "ISLAND"}
    
    -- جزء القائمة بتاعت الاشكال
    if typeKey and typeKey ~= "0" then
        local currentChoice = tonumber(defaultChoice) or 1
        saveState("SKINS_SUB", typeKey .. "|" .. tostring(currentChoice))
        
        local subChoices = {"⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"}
        for _, s in ipairs(skins[typeKey]) do table.insert(subChoices, s.name) end
        table.insert(subChoices, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")
        
        local subChoice = gg.choice(subChoices, currentChoice, "اختر الشكل (" .. typeKey .. ")")
        
        if subChoice == nil then 
            gg.setVisible(false)
        elseif subChoice == 1 or subChoice == #subChoices then 
            saveState("SKINS_SUB", "0")
            skinsMenu(nil)
        else 
            saveState("SKINS_SUB", typeKey .. "|" .. tostring(subChoice))
            applySkins(skins[typeKey][subChoice - 1], typeKey)    
            gg.setVisible(false)
        end
        return
    end

    -- جزء القائمة بتاعت الأقسام 
    saveState("SKINS", "1")
    local choices = {"⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة", "🚂 القطارات", "🚁 الهليكوبتر", "✈️ الطائرات", "🚉 محطة قطار", "?? مهبط هليكوبتر", "🛬 مطار", "🛥 سفينة", "⚓ ميناء", "🐄 بقرة", "🐔 دجاجة", "🐑 خروف", "🐖 خنزير", "🏝️ جزيرة", "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"}
    
    local choice = gg.choice(choices, nil, "المظاهر")
    
    if choice == nil then 
        gg.setVisible(false)
    elseif choice == 1 or choice == #choices then 
        saveState("SKINS", "0")
        mainMenu()
    else 
        saveState("SKINS", "0")
        skinsMenu(keys[choice - 1])
    end
end

function zienaMenu(section, sectionIndex, defaultChoice)
    local currentChoice = tonumber(defaultChoice) or 1
    saveState("Z_MENU", tostring(sectionIndex) .. "|" .. tostring(currentChoice))
    
    local choices = {"⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"}
    for _, item in ipairs(section.items) do
        table.insert(choices, "💎 " .. item.name)
    end
    table.insert(choices, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")

    local choice = gg.choice(choices, currentChoice, section.name)
    
    if choice == nil then 
        gg.setVisible(false)
    elseif choice == 1 or choice == #choices then 
        saveState("Z_MENU", "0")
        categoryMenu()
        else 
        saveState("Z_MENU", tostring(sectionIndex) .. "|" .. tostring(choice))
        applyUnified(section.items[choice - 1])
        gg.setVisible(false)
    end
end


function categoryMenu()
    local catChoices = {"⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"}
    for _, sect in ipairs(config) do table.insert(catChoices, sect.name) end
    table.insert(catChoices, "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة")
    
    saveState("CAT_SELECT", "0")
    local catChoice = gg.choice(catChoices, nil, "🌸 اقسام الزينات 🌸")
    
    if catChoice == nil then 
        gg.setVisible(false)
    elseif catChoice == 1 or catChoice == #catChoices then 
        saveState("MAIN", "0")
        mainMenu()
    else 
        local index = catChoice - 1
        saveState("Z_MENU", index)
        zienaMenu(config[index], index)
    end
end

function expEventMenu()
    saveState("EVENT_MENU", "0") 
    local choices = {
        "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة",
        "📖 إرشادات قبل الاستخدام",
        "✅️ إنجاز الحدث والحصول ع اللقب",
        "⏩️ تبديل الحدث",
        "🔄 إعادة ضبط الحدث",
        "⬅️ عـــــــــــــــــــــــــــــــــــــــــــــودة"
    }
    
    local choice = gg.choice(choices, nil, "🔦 قائمة حدث المغامرة 🔦")
    
    if not choice then
        saveState("EVENT_MENU", "0")

    elseif choice == 1 or choice == 6 then
        mainMenu()

    elseif choice == 2 then
    local msg = "📖 إرشادات قبل الاستخدام\n\n"
    msg = msg .. "استخدم الـ ID الصحيح عند تبديل الحدث.\n\n"
    msg = msg .. "📋 قائمة الأحداث الخاصة بتحديث 38.1.0:\n\n"

    
    local sortedEvents = {eve_searchs["Event 54"], eve_searchs["Event 55"], eve_searchs["Event 56"]}

    for _, v in ipairs(sortedEvents) do
        msg = msg .. "• " .. v.name .. "\n"
        msg = msg .. "ID : " .. v.id .. "\n\n"
    end

    gg.alert(msg)
    expEventMenu()


    elseif choice == 3 then
        finishEventMenu()

    elseif choice == 4 then
        local input = gg.prompt(
    {
        "ما هو الحدث الحالي الموجود ف مدينتك (ID):",
        "ما هو الحدث الذي تريد الانتقال إليه (ID):"
    },
    {"", ""},
    {"number", "number"}
)

        if input then
            changeEvent(
                tonumber(input[1]),
                tonumber(input[2])
            )
        else
            expEventMenu()
        end

    elseif choice == 5 then
        restartEvent()
    end
end

