function selectMemoryRange()

    local choice = gg.choice({
        "📌 نطاق Ca",
        "📌 نطاق O.Others",
        "📌 نطاق Ca + O.Others",
        "⬅️ رجوع"
    }, nil, "⚙️ تغيير نطاقات الذاكرة")

    if not choice then
        mainMenu()
        return
    end

    if choice == 1 then
        gg.setRanges(gg.REGION_C_ALLOC)
        saveMemoryRange("CA")
        gg.toast("✅ تم تفعيل نطاق Ca")

    elseif choice == 2 then
        gg.setRanges(gg.REGION_OTHER)
        saveMemoryRange("OTHER")
        gg.toast("✅ تم تفعيل نطاق O.Others")

    elseif choice == 3 then
        gg.setRanges(gg.REGION_C_ALLOC | gg.REGION_OTHER)
        saveMemoryRange("CA_OTHER")
        gg.toast("✅ تم تفعيل نطاق Ca + O.Others")

    elseif choice == 4 then
        mainMenu()
        return
    end

    mainMenu()
end
-- التشغيل الأولي المحدث
local range = loadMemoryRange()

if range == "CA" then
    gg.setRanges(gg.REGION_C_ALLOC)

elseif range == "OTHER" then
    gg.setRanges(gg.REGION_OTHER)

elseif range == "CA_OTHER" then
    gg.setRanges(gg.REGION_C_ALLOC | gg.REGION_OTHER)
end

while true do
    if gg.isVisible() then 
        gg.setVisible(false) 
        local s, i = loadState()
        
        if s == "Z_MENU" then 
            local p1, p2 = i:match("([^|]+)|(.+)")
            local idx = tonumber(p1)
            if not p1 then idx = tonumber(i) end 
            if idx and config[idx] then
                zienaMenu(config[idx], idx, p2)
            else
                categoryMenu()
            end
     
        elseif s == "SKINS" then 
            skinsMenu(nil)

        elseif s == "SKINS_SUB" then 
            if i ~= "0" then
                local p1, p2 = i:match("([^|]+)|(.+)")
                skinsMenu(p1 or i, p2)
            else
                skinsMenu(nil)
            end

        elseif s == "SUB" then 
            local idx = tonumber(i)
            if idx and config[idx] then
                zienaMenu(config[idx], idx, nil)
            else
                mainMenu()
            end
            
        elseif s == "MATCH3_MENU" then
           match3Menu(i)   
        
        elseif s == "CHAT_MENU" then
           chatMenu()
           
        elseif s == "FRIENDS_MENU" then
           friendsMenu()
    
        elseif s == "BREAK_MENU" then
           breakMenu() 
           
        elseif s == "RES_MAIN_MENU" then
           resMainMenu()  
           
        elseif s == "RES_SUB_MENU" then
           local p1, p2 = i:match("([^|]+)|(.+)")
           local idx = tonumber(p1)
           if not p1 then idx = tonumber(i) end

           if idx and resources[idx] then
              resSubMenu(idx, p2)
           else
              resMainMenu()
          end
          
        elseif s == "ORDER_MENU" then
           orderMenu(i)
           
        elseif s == "TRAIN_CLOVER_MENU" then
     trainAndCloverMenu(tonumber(index))
    
        elseif s == "DEVELOP_MENU" then
           developMenu()  
           
        elseif s == "OV_GIFT_MENU" then
           ov_giftMenu()   
    
        elseif s == "EVENTS_MENU" then
           eventsMenu()
    
        elseif s =="CARDS_MENU" then
           cardsMenu()  
 
        elseif s == "TICKET_MENU" then
            ticketMenu()
            
        elseif s == "PTR_MENU" then
            upgradableDecorsMenu(i ~= "0" and i or nil)

        elseif s == "CAT_SELECT" then
            categoryMenu()

        elseif s == "EVENT_MENU" then
            expEventMenu()
            
        elseif s == "SHOW_EVENTS_MENU" then
           showEventsMenu(i)

        elseif s == "SEARCH_MENU" then
            if i ~= "0" then
                local uInput, c = i:match("([^|]+)|(.+)")
                if uInput then searchByName(c, uInput) end
            else
                mainMenu()
            end
        else 
            mainMenu() 
        end
    end
    gg.sleep(200)
end